import{_ as d}from"./chunks/1732843370764.8F-oWz8G.js";import{_ as r,c as a,o as l,ag as i}from"./chunks/framework.CPtCmog4.js";const p=JSON.parse('{"title":"UDP","description":"","frontmatter":{},"headers":[],"relativePath":"network/UDP.md","filePath":"network/UDP.md","lastUpdated":null}'),e={name:"network/UDP.md"};function o(P,t,n,s,h,U){return l(),a("div",null,t[0]||(t[0]=[i('<h1 id="udp" tabindex="-1">UDP <a class="header-anchor" href="#udp" aria-label="Permalink to &quot;UDP&quot;">​</a></h1><p>UDP(用户数据报协议, User Datagram Protocol) 是一种<strong>无连接的、不可靠的、面向报文的</strong>传输层通信协议，它不提供确认、重传、流量控制和拥塞控制等机制，以最小的开销实现快速的数据传输。</p><h3 id="udp特点" tabindex="-1">UDP特点 <a class="header-anchor" href="#udp特点" aria-label="Permalink to &quot;UDP特点&quot;">​</a></h3><ul><li>无连接：发送数据前不需要建立连接，减少开销和延迟</li><li>不可靠：不保证数据到达、不保证顺序、不保证不重复，尽最大努力交付</li><li>面向报文：应用层交下来的报文，UDP不合并也不拆分，保留原有边界直接发送</li><li>无拥塞控制：网络拥塞不会降低发送速率，适合实时应用</li><li>支持一对一、一对多、多对一、多对多通信（广播/多播）</li><li>首部开销小：仅8字节（TCP首部至少20字节）</li></ul><h3 id="udp报文结构" tabindex="-1">UDP报文结构 <a class="header-anchor" href="#udp报文结构" aria-label="Permalink to &quot;UDP报文结构&quot;">​</a></h3><img src="'+d+'" alt="UDP报文结构" style="zoom:60%;"><p>UDP报文由首部和数据两部分组成，首部仅8字节，结构如下：</p><table tabindex="0"><thead><tr><th>字段</th><th>长度</th><th>说明</th></tr></thead><tbody><tr><td>源端口</td><td>16 bit</td><td>发送方端口号，可全0（不需要回复时）</td></tr><tr><td>目的端口</td><td>16 bit</td><td>接收方端口号</td></tr><tr><td>长度</td><td>16 bit</td><td>UDP数据报的总长度（首部+数据），最小值为8</td></tr><tr><td>校验和</td><td>16 bit</td><td>检验UDP数据报在传输中是否有错，可选字段</td></tr></tbody></table><p>注意：</p><ul><li>校验和的计算需要加上12字节的伪首部（源IP、目的IP、协议号、UDP长度），伪首部仅在计算校验和时使用，不实际传输</li><li>UDP校验和是可选的（IPv4中），若不计算校验和则填0；但IPv6中校验和是必选的</li><li>UDP数据报的最大长度理论上为65535字节（受IP报文长度限制），但实际受MTU限制，超过MTU时会在IP层分片</li></ul><h3 id="udp-vs-tcp" tabindex="-1">UDP vs TCP <a class="header-anchor" href="#udp-vs-tcp" aria-label="Permalink to &quot;UDP vs TCP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>特性</th><th>UDP</th><th>TCP</th></tr></thead><tbody><tr><td>连接性</td><td>无连接</td><td>面向连接</td></tr><tr><td>可靠性</td><td>不可靠</td><td>可靠</td></tr><tr><td>传输方式</td><td>面向报文</td><td>面向字节流</td></tr><tr><td>通信模式</td><td>一对一/一对多/多对多</td><td>仅一对一</td></tr><tr><td>首部开销</td><td>8字节</td><td>20~60字节</td></tr><tr><td>传输效率</td><td>高</td><td>较低</td></tr><tr><td>流量控制</td><td>无</td><td>滑动窗口</td></tr><tr><td>拥塞控制</td><td>无</td><td>慢开始/拥塞避免/快重传/快恢复</td></tr><tr><td>顺序保证</td><td>无</td><td>有</td></tr><tr><td>适用场景</td><td>实时音视频、DNS、游戏</td><td>文件传输、网页浏览、邮件</td></tr></tbody></table><h3 id="udp的适用场景" tabindex="-1">UDP的适用场景 <a class="header-anchor" href="#udp的适用场景" aria-label="Permalink to &quot;UDP的适用场景&quot;">​</a></h3><ul><li><strong>实时音视频通信</strong>：对延迟敏感，偶尔丢包可接受（如视频会议、直播）</li><li><strong>DNS查询</strong>：查询报文短小，需要快速响应，UDP足够可靠</li><li><strong>在线游戏</strong>：对实时性要求高，允许少量丢包（如位置同步）</li><li><strong>SNMP网络管理</strong>：管理报文简短，UDP开销小</li><li><strong>流媒体传输</strong>：如RTP/RTCP协议基于UDP</li><li><strong>广播/多播</strong>：UDP支持一对多通信，适合广播场景（如IPTV、服务发现）</li></ul><h3 id="udp的可靠性增强" tabindex="-1">UDP的可靠性增强 <a class="header-anchor" href="#udp的可靠性增强" aria-label="Permalink to &quot;UDP的可靠性增强&quot;">​</a></h3><p>虽然UDP本身不可靠，但应用层可以通过自定义协议来增强其可靠性：</p><ul><li><strong>确认机制</strong>：接收方返回ACK确认，发送方据此判断是否重传</li><li><strong>超时重传</strong>：发送方设置定时器，超时未收到ACK则重传</li><li><strong>序列号</strong>：为每个数据包编号，接收方可以检测丢包和乱序</li><li><strong>校验与纠错</strong>：使用校验和检测错误，使用前向纠错（FEC）恢复丢失数据</li></ul><p>常见的UDP可靠性增强方案：</p><table tabindex="0"><thead><tr><th>方案</th><th>特点</th></tr></thead><tbody><tr><td>QUIC</td><td>Google提出的传输协议，基于UDP实现了类似TCP的可靠性+多路复用，HTTP/3的基础</td></tr><tr><td>KCP</td><td>快速可靠协议，在UDP上实现ARQ（自动重传请求），牺牲带宽换取低延迟</td></tr><tr><td>UDT</td><td>面向大数据传输的UDP协议，支持可靠传输和拥塞控制</td></tr><tr><td>SCTP</td><td>流控制传输协议，支持多宿主和多流，兼具TCP和UDP的优点</td></tr></tbody></table><h3 id="udp分片" tabindex="-1">UDP分片 <a class="header-anchor" href="#udp分片" aria-label="Permalink to &quot;UDP分片&quot;">​</a></h3><p>当UDP数据报长度超过MTU（通常为1500字节）时，会在IP层进行分片：</p><ul><li>分片在IP层完成，对UDP层透明</li><li>任一分片丢失，整个数据报被丢弃（IP层无重传机制）</li><li>因此建议应用层控制UDP数据报大小不超过MTU - IP首部 - UDP首部 = 1500 - 20 - 8 = 1472字节</li><li>使用<code>path MTU发现</code>机制可以避免IP分片，提高传输效率</li></ul>',22)]))}const b=r(e,[["render",o]]);export{p as __pageData,b as default};
